package vn.covie.checkout.application; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.util.HexFormat; import org.springframework.stereotype.Component; @Component public class CheckoutTokenHasher{public String hash(String token){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(token.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}}
